import { useMemo } from 'react'
import { createPortal } from 'react-dom'
import { documentTitle, parseResume, type ResumeLayout } from '../lib/resumeLayout'

// A clean, single-column page made from the resume text, and "Save as PDF" through the browser's
// print dialog (no PDF library, nothing sent anywhere). Only the resume is printed: a second copy is
// placed straight under <body> and the print stylesheet (index.css) hides everything else, so the
// page has no menu, buttons or notes. Nothing is added to the text: no "generated by", no marks.
export default function ResumePreview({ text }: { text: string }) {
  const layout = useMemo(() => parseResume(text), [text])
  if (layout.name === null && layout.sections.length === 0) return null

  // Browsers use the page title as the PDF's file name, so it is set to the person's name while the
  // print dialog is open, then put back.
  function savePdf() {
    const previous = document.title
    document.title = documentTitle(layout)
    const restore = () => {
      document.title = previous
      window.removeEventListener('afterprint', restore)
    }
    window.addEventListener('afterprint', restore)
    window.print()
  }

  return (
    <section className="card-glow rounded-xl bg-surface-card p-5 space-y-3">
      <div className="flex items-center justify-between gap-3">
        <h2 className="text-sm font-medium text-slate-900">Preview</h2>
        <button
          onClick={savePdf}
          className="px-3 py-1.5 rounded-lg text-sm font-medium bg-brand-600 text-white hover:bg-brand-700"
        >
          Save as PDF
        </button>
      </div>
      <p className="text-xs text-slate-500">
        Choose "Save as PDF" as the destination in the print window. If the page shows a web address or date, turn off
        "Headers and footers" in the print options. The file is named after you.
      </p>
      <div className="rounded-lg border border-surface-border bg-white p-6 sm:p-8 overflow-x-auto">
        <ResumeDocument layout={layout} />
      </div>
      {createPortal(
        <div className="resume-print-root hidden print:block">
          <ResumeDocument layout={layout} />
        </div>,
        document.body,
      )}
    </section>
  )
}

function ResumeDocument({ layout }: { layout: ResumeLayout }) {
  return (
    <article className="text-[11pt] leading-snug text-black" style={{ fontFamily: 'Inter, Arial, sans-serif' }}>
      {layout.name && (
        <header className="text-center mb-3">
          <h1 className="text-[20pt] font-bold leading-tight">{layout.name}</h1>
          {layout.contact.map((line, i) => (
            <p key={i} className="text-[10pt] text-neutral-700">
              {line}
            </p>
          ))}
        </header>
      )}
      {layout.sections.map((section, s) => (
        <section key={s} className="mb-3" style={{ breakInside: 'auto' }}>
          {section.heading && (
            <h2 className="text-[10.5pt] font-bold uppercase tracking-wider border-b border-neutral-400 pb-0.5 mb-1.5">
              {section.heading}
            </h2>
          )}
          <Items items={section.items} />
        </section>
      ))}
    </article>
  )
}

// Consecutive bullets share one list.
function Items({ items }: { items: ResumeLayout['sections'][number]['items'] }) {
  const out: React.ReactNode[] = []
  for (let i = 0; i < items.length; i++) {
    const item = items[i]!
    if (item.kind === 'bullet') {
      const run: string[] = []
      while (items[i]?.kind === 'bullet') run.push((items[i++] as { text: string }).text)
      i--
      out.push(
        <ul key={i} className="list-disc ml-5 space-y-0.5 my-0.5">
          {run.map((text, n) => (
            <li key={n} style={{ breakInside: 'avoid' }}>
              {text}
            </li>
          ))}
        </ul>,
      )
    } else if (item.kind === 'gap') {
      out.push(<div key={i} className="h-1.5" />)
    } else {
      out.push(
        <p key={i} className={item.kind === 'role' ? 'font-semibold mt-1' : undefined} style={{ breakAfter: item.kind === 'role' ? 'avoid' : 'auto' }}>
          {item.text}
        </p>,
      )
    }
  }
  return <>{out}</>
}
